contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public {
        require(v != 0);
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        require(before == 0);
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint afterVal = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(afterVal == v);
    }

    receive() external payable {}
}

