pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v) internal {
        vm.assume(v != 0);
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        vm.assume(before == 0);
        try c.SetMinSum(v) {} catch { return; }
        uint256 afterVal;
        try c.MinSum() returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(afterVal == v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
